//! 🏘️ Typed thermal envelope, vertices, layers and shade entities.
use super::*;
const ZONE:&[FloatColumn]=&[FloatColumn::Binary64(5)];
const SPACE:&[FloatColumn]=&[FloatColumn::Binary64(6)];
const FENESTRATION:&[FloatColumn]=&[FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10),FloatColumn::Binary64(11),FloatColumn::Binary64(12),FloatColumn::Binary64(13),FloatColumn::Binary64(14),FloatColumn::Binary64(15),FloatColumn::Binary64(16),FloatColumn::Binary64(17)];
const MATERIAL:&[FloatColumn]=&[FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10),FloatColumn::Binary64(11),FloatColumn::Binary64(12)];
const GLAZING:&[FloatColumn]=&[FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10),FloatColumn::Binary64(11),FloatColumn::Binary64(12),FloatColumn::Binary64(13),FloatColumn::Binary64(14),FloatColumn::Binary64(15)];
const GAS:&[FloatColumn]=&[FloatColumn::Binary64(5)];
fn surface_class(v:SurfaceClass)->&'static str{match v{SurfaceClass::ExteriorWall=>"ExteriorWall",SurfaceClass::InteriorWall=>"InteriorWall",SurfaceClass::Roof=>"Roof",SurfaceClass::Ceiling=>"Ceiling",SurfaceClass::Floor=>"Floor",SurfaceClass::Interzone=>"Interzone",SurfaceClass::Adiabatic=>"Adiabatic",SurfaceClass::Ground=>"Ground"}}
fn read_class(v:&str)->Result<SurfaceClass,ValueError>{match v{"ExteriorWall"=>Ok(SurfaceClass::ExteriorWall),"InteriorWall"=>Ok(SurfaceClass::InteriorWall),"Roof"=>Ok(SurfaceClass::Roof),"Ceiling"=>Ok(SurfaceClass::Ceiling),"Floor"=>Ok(SurfaceClass::Floor),"Interzone"=>Ok(SurfaceClass::Interzone),"Adiabatic"=>Ok(SurfaceClass::Adiabatic),"Ground"=>Ok(SurfaceClass::Ground),_=>Err(invalid("Energy surface class differs"))}}
fn roughness(v:SurfaceRoughness)->&'static str{match v{SurfaceRoughness::VeryRough=>"VeryRough",SurfaceRoughness::Rough=>"Rough",SurfaceRoughness::MediumRough=>"MediumRough",SurfaceRoughness::MediumSmooth=>"MediumSmooth",SurfaceRoughness::Smooth=>"Smooth",SurfaceRoughness::VerySmooth=>"VerySmooth"}}
fn read_roughness(v:&str)->Result<SurfaceRoughness,ValueError>{match v{"VeryRough"=>Ok(SurfaceRoughness::VeryRough),"Rough"=>Ok(SurfaceRoughness::Rough),"MediumRough"=>Ok(SurfaceRoughness::MediumRough),"MediumSmooth"=>Ok(SurfaceRoughness::MediumSmooth),"Smooth"=>Ok(SurfaceRoughness::Smooth),"VerySmooth"=>Ok(SurfaceRoughness::VerySmooth),_=>Err(invalid("Energy roughness differs"))}}
fn gas(v:GasKind)->&'static str{match v{GasKind::Air=>"Air",GasKind::Argon=>"Argon",GasKind::Krypton=>"Krypton",GasKind::Xenon=>"Xenon"}}
fn read_gas(v:&str)->Result<GasKind,ValueError>{match v{"Air"=>Ok(GasKind::Air),"Argon"=>Ok(GasKind::Argon),"Krypton"=>Ok(GasKind::Krypton),"Xenon"=>Ok(GasKind::Xenon),_=>Err(invalid("Energy glazing gas differs"))}}
pub(super)fn project(m:&Model,p:&mut Projection<'_,'_>)->Result<(),ValueError>{
 for(n,v)in m.zones.iter().enumerate(){emit(p,"energy_zone",n,&[i(v.id.0),Cell::Text(&v.name),Cell::Real(v.volume_m3),i(v.multiplier),b(v.conditioned),b(v.part_of_total_floor_area)],ZONE)?;}
 for(n,v)in m.spaces.iter().enumerate(){emit(p,"energy_space",n,&[i(v.id.0),Cell::Text(&v.name),i(v.zone_id.0),Cell::Real(v.floor_area_m2)],SPACE)?;}
 for(n,v)in m.surfaces.iter().enumerate(){let(kind,partner)=match v.outside_boundary_condition{OutsideBoundary::OutdoorAir=>("OutdoorAir",Cell::Null),OutsideBoundary::Ground=>("Ground",Cell::Null),OutsideBoundary::OtherSideTemperature=>("OtherSideTemperature",Cell::Null),OutsideBoundary::Adiabatic=>("Adiabatic",Cell::Null),OutsideBoundary::Interzone(id)=>("Interzone",i(id.0))};let parent=emit(p,"energy_surface",n,&[i(v.id.0),Cell::Text(&v.name),i(v.zone_id.0),Cell::Text(surface_class(v.class)),i(v.construction_id.0),Cell::Text(kind),partner,b(v.sun_exposed),b(v.wind_exposed),i(v.multiplier)],&[])?;vertices(p,"energy_surface_vertex",parent,&v.vertices_m)?;}
 for(n,v)in m.fenestrations.iter().enumerate(){let parent=emit(p,"energy_fenestration",n,&[i(v.id.0),Cell::Text(&v.name),i(v.surface_id.0),Cell::Real(v.u_value_w_m2k),Cell::Real(v.shgc),Cell::Real(v.vlt),Cell::Real(v.area_m2),Cell::Real(v.height_m),Cell::Real(v.sill_height_m),Cell::Real(v.frame_conductance_w_k),Cell::Real(v.divider_conductance_w_k),Cell::Real(v.overhang_depth_m),Cell::Real(v.overhang_offset_m),Cell::Real(v.fin_depth_m),Cell::Real(v.fin_offset_m),optional_id(v.glazing_construction_id)],FENESTRATION)?;vertices(p,"energy_fenestration_vertex",parent,&v.vertices_m)?;}
 for(n,v)in m.materials.iter().enumerate(){emit(p,"energy_material",n,&[i(v.id.0),Cell::Text(&v.name),Cell::Text(roughness(v.roughness)),Cell::Real(v.thickness_m),Cell::Real(v.conductivity_w_m_k),Cell::Real(v.density_kg_m3),Cell::Real(v.specific_heat_j_kg_k),Cell::Real(v.thermal_absorptance),Cell::Real(v.solar_absorptance),Cell::Real(v.visible_absorptance)],MATERIAL)?;}
 for(n,v)in m.glazing_materials.iter().enumerate(){emit(p,"energy_glazing_material",n,&[i(v.id.0),Cell::Text(&v.name),Cell::Real(v.thickness_m),Cell::Real(v.conductivity_w_m_k),Cell::Real(v.solar_transmittance),Cell::Real(v.solar_reflectance_front),Cell::Real(v.solar_reflectance_back),Cell::Real(v.visible_transmittance),Cell::Real(v.visible_reflectance_front),Cell::Real(v.visible_reflectance_back),Cell::Real(v.infrared_transmittance),Cell::Real(v.infrared_emissivity_front),Cell::Real(v.infrared_emissivity_back)],GLAZING)?;}
 for(n,v)in m.gas_materials.iter().enumerate(){emit(p,"energy_gas_material",n,&[i(v.id.0),Cell::Text(&v.name),Cell::Real(v.thickness_m),Cell::Text(gas(v.gas))],GAS)?;}
 for(n,v)in m.constructions.iter().enumerate(){let parent=emit(p,"energy_construction",n,&[i(v.id.0),Cell::Text(&v.name)],&[])?;ids(p,"energy_construction_layer",parent,&v.layer_material_ids)?;}
 for(n,v)in m.shading_surfaces.iter().enumerate(){let parent=emit(p,"energy_shading_surface",n,&[i(v.id.0),Cell::Text(&v.name),optional_schedule(v.transmittance_schedule_id)],&[])?;vertices(p,"energy_shading_vertex",parent,&v.vertices_m)?;}
 for(n,v)in m.space_lists.iter().enumerate(){let parent=emit(p,"energy_space_list",n,&[i(v.id.0),Cell::Text(&v.name)],&[])?;ids(p,"energy_space_list_member",parent,&v.space_ids)?;}
 for(n,v)in m.thermal_enclosures.iter().enumerate(){let parent=emit(p,"energy_thermal_enclosure",n,&[i(v.id.0),Cell::Text(&v.name)],&[])?;ids(p,"energy_thermal_enclosure_zone",parent,&v.zone_ids)?;}
 for(n,v)in m.adjacency_pairs.iter().enumerate(){emit(p,"energy_adjacency_pair",n,&[i(v.surface_a_id.0),i(v.surface_b_id.0)],&[])?;}Ok(())
}
pub(super)fn reconstruct(m:&mut Model,r:&mut Reader<'_,'_,'_>)->Result<(),ValueError>{
 for v in r.rows("energy_zone",1,9,ZONE)?{m.zones.push(Zone{id:entity(v,3)?,name:r.text(v,4)?,volume_m3:v.real(5)?,multiplier:u32_value(v,6)?,conditioned:boolean(v,7)?,part_of_total_floor_area:boolean(v,8)?});}
 for v in r.rows("energy_space",1,7,SPACE)?{m.spaces.push(Space{id:entity(v,3)?,name:r.text(v,4)?,zone_id:entity(v,5)?,floor_area_m2:v.real(6)?});}
 for v in r.rows("energy_surface",1,13,&[])?{let partner=optional_entity(v,9)?;let boundary=match(v.text(8)?,partner){("OutdoorAir",None)=>OutsideBoundary::OutdoorAir,("Ground",None)=>OutsideBoundary::Ground,("OtherSideTemperature",None)=>OutsideBoundary::OtherSideTemperature,("Adiabatic",None)=>OutsideBoundary::Adiabatic,("Interzone",Some(id))=>OutsideBoundary::Interzone(id),_=>return Err(invalid("Energy boundary tag or presence differs"))};m.surfaces.push(Surface{id:entity(v,3)?,name:r.text(v,4)?,zone_id:entity(v,5)?,class:read_class(v.text(6)?)?,construction_id:entity(v,7)?,outside_boundary_condition:boundary,sun_exposed:boolean(v,10)?,wind_exposed:boolean(v,11)?,multiplier:u32_value(v,12)?,vertices_m:read_vertices(r,"energy_surface_vertex",v.rowid)?});}
 for v in r.rows("energy_fenestration",1,19,FENESTRATION)?{m.fenestrations.push(Fenestration{id:entity(v,3)?,name:r.text(v,4)?,surface_id:entity(v,5)?,u_value_w_m2k:v.real(6)?,shgc:v.real(7)?,vlt:v.real(8)?,area_m2:v.real(9)?,height_m:v.real(10)?,sill_height_m:v.real(11)?,frame_conductance_w_k:v.real(12)?,divider_conductance_w_k:v.real(13)?,overhang_depth_m:v.real(14)?,overhang_offset_m:v.real(15)?,fin_depth_m:v.real(16)?,fin_offset_m:v.real(17)?,glazing_construction_id:optional_entity(v,18)?,vertices_m:read_vertices(r,"energy_fenestration_vertex",v.rowid)?});}
 for v in r.rows("energy_material",1,13,MATERIAL)?{m.materials.push(Material{id:entity(v,3)?,name:r.text(v,4)?,roughness:read_roughness(v.text(5)?)?,thickness_m:v.real(6)?,conductivity_w_m_k:v.real(7)?,density_kg_m3:v.real(8)?,specific_heat_j_kg_k:v.real(9)?,thermal_absorptance:v.real(10)?,solar_absorptance:v.real(11)?,visible_absorptance:v.real(12)?});}
 for v in r.rows("energy_glazing_material",1,16,GLAZING)?{m.glazing_materials.push(GlazingMaterial{id:entity(v,3)?,name:r.text(v,4)?,thickness_m:v.real(5)?,conductivity_w_m_k:v.real(6)?,solar_transmittance:v.real(7)?,solar_reflectance_front:v.real(8)?,solar_reflectance_back:v.real(9)?,visible_transmittance:v.real(10)?,visible_reflectance_front:v.real(11)?,visible_reflectance_back:v.real(12)?,infrared_transmittance:v.real(13)?,infrared_emissivity_front:v.real(14)?,infrared_emissivity_back:v.real(15)?});}
 for v in r.rows("energy_gas_material",1,7,GAS)?{m.gas_materials.push(GasMaterial{id:entity(v,3)?,name:r.text(v,4)?,thickness_m:v.real(5)?,gas:read_gas(v.text(6)?)?});}
 for v in r.rows("energy_construction",1,5,&[])?{m.constructions.push(Construction{id:entity(v,3)?,name:r.text(v,4)?,layer_material_ids:read_ids(r,"energy_construction_layer",v.rowid)?});}
 for v in r.rows("energy_shading_surface",1,6,&[])?{m.shading_surfaces.push(ShadingSurface{id:entity(v,3)?,name:r.text(v,4)?,transmittance_schedule_id:optional_schedule_value(v,5)?,vertices_m:read_vertices(r,"energy_shading_vertex",v.rowid)?});}
 for v in r.rows("energy_space_list",1,5,&[])?{m.space_lists.push(SpaceList{id:entity(v,3)?,name:r.text(v,4)?,space_ids:read_ids(r,"energy_space_list_member",v.rowid)?});}
 for v in r.rows("energy_thermal_enclosure",1,5,&[])?{m.thermal_enclosures.push(ThermalEnclosure{id:entity(v,3)?,name:r.text(v,4)?,zone_ids:read_ids(r,"energy_thermal_enclosure_zone",v.rowid)?});}
 for v in r.rows("energy_adjacency_pair",1,5,&[])?{m.adjacency_pairs.push(AdjacencyPair{surface_a_id:entity(v,3)?,surface_b_id:entity(v,4)?});}Ok(())
}
